<?php
declare(strict_types=1);require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';require_once __DIR__.'/noa-bridge/creator-core.php';require_once __DIR__.'/noa-bridge/sound-core.php';require_once __DIR__.'/noa-app/jukebox/core.php';
header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-store');$id=$_GET['id']??'';if(!is_string($id)||!preg_match('/^[a-f0-9]{64}$/D',$id)){http_response_code(404);exit;}
function nch_e(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
try{$db=noa_bridge_pdo();$channel=nc_row($db,'creator-channel:'.$id);if(!$channel){http_response_code(404);exit;}$songs=[];$owner=$channel['document']['ownerId']??'';$records=$owner!==''?nc_owned_records($db,$owner):[];if($owner===''){$q=$db->prepare("SELECT doc_key,kind,payload,revision FROM noa_documents WHERE kind IN ('single','story') AND SHA2(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.ownerId')),256)=?");$q->execute([$id]);$records=$q->fetchAll(PDO::FETCH_ASSOC);}foreach($records as $r){$d=json_decode($r['payload'],true,512,JSON_THROW_ON_ERROR);if($r['kind']==='playlist'||!empty($d['_noaTrash'])||($d['visibility']??'public')!=='public'||hash('sha256',(string)($d['ownerId']??''))!==$id)continue;$asset=nj_find($db,$r['doc_key']);if(nj_verified($asset,'audio'))$songs[]=['key'=>$r['doc_key'],'title'=>$d['title'],'youtubeUrl'=>$d['body']['youtubeUrl']??''];}}catch(Throwable $e){http_response_code(503);exit('채널을 불러오지 못했습니다.');}
$access=nam_access((array)($member??[]),(string)($is_admin??''));
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=nch_e($channel['document']['title'])?> | NOA STUDIO</title><link rel="stylesheet" href="/noa-ui.css"><link rel="stylesheet" href="/noa-creator.css"><script src="/noa-brand.js" defer></script><script src="/noa-ui.js" defer></script></head><body class="noa-page"><main><p class="noa-eyebrow">CREATOR CHANNEL</p><img width="96" height="96" style="border-radius:24px;object-fit:cover" src="/noa-creator-symbol.php?channel=<?=nch_e($id)?>" alt="채널 대표 심볼"><h1><?=nch_e($channel['document']['title'])?></h1><p><?=nl2br(nch_e($channel['document']['description']))?></p><?php if(!empty($channel['document']['boardId'])):?><a class="noa-button" data-noa-icon="community" href="/bbs/board.php?bo_table=<?=nch_e($channel['document']['boardId'])?>">채널 게시판</a><?php endif;?><section class="noa-section"><h2>공개한 곡</h2><?php if(!$songs):?><p>아직 공개한 곡이 없습니다.</p><?php endif;?><?php foreach($songs as $song):?><article class="creator-row"><span><strong><?=nch_e($song['title'])?></strong><?php if($access['music']):?><audio controls controlslist="nodownload" preload="none" src="<?=nch_e(nj_url($song['key'],'audio'))?>"></audio><?php else:?><small>음원 재생은 VIP회원·VIP 크리에이터가 이용할 수 있습니다.</small><?php endif;?></span><a class="noa-button" data-noa-icon="youtube" href="/noa-youtube.php?track=<?=rawurlencode('coming:'.hash('sha256','song:'.$song['key']))?>">YouTube 목록</a></article><?php endforeach;?></section></main></body></html>
